mapper.select:
select
    count(1)
from hotel_booking hk
join hotel_room hr on hr.room_id=hk.room_id
where hr.hotel_id=#{hotelId}
    and hr.room_no=#{roomNo}
    and hk.status IN (0, 1, 2)
    and hk.check_in_date <= #{checkInDate}
    and hk.check_out_date >= #{checkInDate}

select
    hr.room_id
from hotel_room hr
where hr.hotel_id = #{hotelId}
  and hr.room_type_id = #{roomTypeId}
  and hr.room_no = #{roomNo}
  and hr.status = 1  -- 房间本身可用（未被禁用）
  and not exists(
      select 1 from hotel_booking hb
      where hb.room_id = hr.room_id
        and hb.status in (0, 1, 2)  -- 待支付、已支付、已确认
        and hb.check_in_date < #{checkOutDate}
        and hb.check_out_date > #{checkInDate}
  )
limit 1
